import { ref } from 'vue';

export default {
  name: 'EffectDemo',
  setup() {
    const count = ref(0);
    const effectMessage = ref('');
    const layoutEffectRanLast = ref(false);

    const increment = () => {
      count.value++;
    };

    // useEffect equivalent
    import { onMounted, onUpdated } from 'vue';
    onMounted(() => {
      effectMessage.value = 'useEffect: Component mounted';
      layoutEffectRanLast.value = false;
    });
    onUpdated(() => {
      effectMessage.value = 'useEffect: Component updated';
      layoutEffectRanLast.value = false;
    });

    // useLayoutEffect equivalent
    import { nextTick } from 'vue';
    nextTick(() => {
      effectMessage.value = 'useLayoutEffect: DOM updated';
      layoutEffectRanLast.value = true;
    });

    return {
      count,
      effectMessage,
      layoutEffectRanLast,
      increment
    };
  },
  template: `
    <div>
      <h1>Count: {{ count }}</h1>
      <p>{{ effectMessage }}</p>
      <button @click="increment">Increment</button>
      <!-- Add visual feedback div here -->
    </div>
  `
};

